// Le même format que « Vitrines · Envoi des maquettes » : texte de Basile, liens cliquables, lien de désinscription.
const NL = String.fromCharCode(10);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const liens = (s) => s.replace(/https:\/\/[^\s<]+/g, (u) => '<a href="' + u + '">' + u + '</a>');
const out = [];
for (const it of $input.all()) {
  const d = it.json || {};
  if (!d.id || !d.to_email || !d.corps) continue;
  const fromEmail = d.from_email || 'contact@raime.fr';
  const fromName = d.from_name || 'rAIme';
  const desinscription = 'https://cockpit.raime.fr/unsub?e=' + encodeURIComponent(d.to_email);
  const html = '<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:15px;line-height:1.6;color:#1a1a1a">'
    + liens(esc(d.corps)).split(NL).join('<br>')
    + '<p style="font-size:11px;color:#999999;margin-top:22px">' + esc(fromEmail) + ' · <a href="' + desinscription + '" style="color:#999999">se désinscrire</a></p></div>';
  out.push({ json: { id: d.id, email_body: { from: fromName + ' <' + fromEmail + '>', to: [d.to_email], reply_to: fromEmail,
    subject: d.sujet || 'Votre site', html, text: d.corps + NL + NL + 'Se désinscrire : ' + desinscription,
    headers: { 'List-Unsubscribe': '<' + desinscription + '>' } } } });
}
return out;

// L'e-mail est marqué selon SA réponse de Resend : un identifiant = parti ; sinon « erreur » avec le message.
const e = $('Prepare').first();
const r = ($input.first() || { json: {} }).json || {};
const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
const ok = typeof r.id === 'string' && /^[A-Za-z0-9-]{8,64}$/.test(r.id) && !r.statusCode && !r.error;
const erreur = ok ? null : String(r.message || (r.error && (r.error.message || r.error)) || 'réponse inattendue de Resend').slice(0, 200);
const sql = 'UPDATE vitrines_apres_appel SET statut = ' + q(ok ? 'envoye' : 'erreur') + ', resend_id = ' + (ok ? q(r.id) : 'NULL')
  + ', erreur = ' + (erreur === null ? 'NULL' : q(erreur)) + ', envoye_le = ' + (ok ? 'now()' : 'NULL')
  + ' WHERE id = ' + Number(e.json.id) + " AND statut = 'a_envoyer' RETURNING id, statut, erreur;";
return [{ json: { sql } }];
